110	        List<Pet> sortedPets = new ArrayList<>(getPetsInternal());
111	        sortedPets.sort(Comparator.comparing(Pet::getName, String.CASE_INSENSITIVE_ORDER));
112	        return Collections.unmodifiableList(sortedPets);
